          hasOpenrouterApiKey: Boolean(openrouterApiKey),
          provider: providerName,
        });
      }

      const action = await provider.next({
        prompt,
        model,
        reasoningEffort,
        maxSteps: providerLoopMaxSteps,
        step,
        history,
        forceComplete: forceCompleteNextStep,
      });
      forceCompleteNextStep = false;

